def fill(t, bound, fillv, maxgap):
    o=t.copy(); H,W=t.shape
    for r in range(H):
        for c in range(W):
            if t[r,c]==fillv:
                row=t[r]; col=t[:,c]
                def run(line,i):
                    # nearest bound left/right
                    L=None
                    for j in range(i-1,-1,-1):
                        if line[j]==bound: L=j; break
                    R=None
                    for j in range(i+1,len(line)):
                        if line[j]==bound: R=j; break
                    return (L is not None and R is not None and R-L-1<=maxgap)
                if run(row,c) or run(col,r): o[r,c]=2
    return o
