def pairs_fill(g, m, T):
    o = g.copy(); H,W = g.shape
    for r in range(H):
        idx = np.where(g[r]==m)[0]
        for a,b in zip(idx[:-1],idx[1:]):
            if b-a-1 <= T: o[r,a+1:b] = 2
    for c in range(W):
        idx = np.where(g[:,c]==m)[0]
        for a,b in zip(idx[:-1],idx[1:]):
            if b-a-1 <= T: o[a+1:b,c] = 2
    return o
